def solve_cvrp(instance):
    """
    Deterministic constructive + repair CVRP solver.

    Assumptions:
    - instance is a dict with:
        - 'customers': list of dicts with 'id' (int) and 'demand' (int) and optional 'x','y'
        - 'depot': int id of depot (not included in routes)
        - 'capacity': int vehicle capacity
    - Return: list of routes, each route is [customer_id, ...] (no depot)
    """
    # Extract data with safe defaults
    customers = instance.get('customers', [])
    depot_id = instance.get('depot', 0)
    capacity = instance.get('capacity', 0)

    # Build a clean list of customers (exclude depot)
    custs = []
    for c in customers:
        cid = c.get('id', None)
        if cid is None or cid == depot_id:
            continue
        demand = int(c.get('demand', 0))
        x = c.get('x', None)
        y = c.get('y', None)
        custs.append({'id': cid, 'demand': demand, 'x': x, 'y': y})

    if not custs:
        return []

    # Distance helper (deterministic)
    def dist(a, b):
        ax = a.get('x'); ay = a.get('y')
        bx = b.get('x'); by = b.get('y')
        if ax is not None and ay is not None and bx is not None and by is not None:
            return abs(ax - bx) + abs(ay - by)
        return abs(a['id'] - b['id'])

    # Sort by deterministic criteria: by demand then by id
    custs_sorted = sorted(custs, key=lambda c: (c['demand'], c['id']))

    # Build initial routes greedily: fill as much as possible per route in sorted order
    routes = []
    current_route = []
    current_load = 0
    id_to_cust = {c['id']: c for c in custs_sorted}

    for c in custs_sorted:
        if current_load + c['demand'] <= capacity:
            current_route.append(c['id'])
            current_load += c['demand']
        else:
            if current_route:
                routes.append(current_route)
            current_route = [c['id']]
            current_load = c['demand']
    if current_route:
        routes.append(current_route)

    # Repair: ensure no single customer exceeds capacity; split if needed
    final_routes = []
    for r in routes:
        if not r:
            continue
        temp = []
        load = 0
        for cid in r:
            d = id_to_cust[cid]['demand']
            if d > capacity:
                if temp:
                    final_routes.append(temp)
                    temp = []
                    load = 0
                final_routes.append([cid])
            else:
                if load + d <= capacity:
                    temp.append(cid)
                    load += d
                else:
                    if temp:
                        final_routes.append(temp)
                    temp = [cid]
                    load = d
        if temp:
            final_routes.append(temp)

    # Filter empty and return
    final_routes = [route for route in final_routes if route]
    return final_routes

